"""tabula.engine -- the table model, the transforms, the output formats and the command line.

This is the one module every command lives in. A command is a function `cmd_NAME(args, opts)` that gets the
positional arguments (a list of strings) and the options (a dict) and returns a Table, which `main` then prints in the
format asked for (`--format text|csv|json`, text by default). A mistake in a file or in a request raises TabulaError
(exit status 1); a command line that is not shaped right raises UsageError (exit status 2).
"""
import csv
import io
import json
import os
import re
import sys
import unicodedata
from decimal import (Decimal, InvalidOperation, ROUND_HALF_UP, ROUND_FLOOR, ROUND_CEILING, ROUND_DOWN, getcontext,
                     localcontext, MAX_PREC, MAX_EMAX, MIN_EMIN)

from .errors import TabulaError, UsageError

PROG = "tabula"
FORMATS = ("text", "csv", "json")
# The options that take a value: name -> (allowed values, default). `parse_args` reads them all the same way.
VALUE_OPTIONS = {
    "format": (FORMATS, "text"),
    "kind": (("inner", "left"), "inner"),
    "keep": (("first", "last"), "first"),
}
getcontext().prec = 60

NUMBER = re.compile(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)")


# --- numbers -------------------------------------------------------------------------------------------------

def to_decimal(text):
    """The Decimal a cell holds, or None when it is not a plain decimal number (no exponent, no thousands marks)."""
    text = text.strip()
    if not NUMBER.fullmatch(text):
        return None
    try:
        return Decimal(text)
    except InvalidOperation:
        return None


def fmt_decimal(number):
    """A Decimal as plain text: no exponent, no negative zero."""
    text = format(number, "f")
    if text.startswith("-") and not text.strip("-0."):
        text = text[1:]
    return text


def exact_sum(numbers):
    """The exact sum of Decimals, whatever their length (the module context rounds at 60 digits)."""
    with localcontext() as ctx:
        ctx.prec, ctx.Emax, ctx.Emin = MAX_PREC, MAX_EMAX, MIN_EMIN
        return sum(numbers, Decimal(0))


def fmt_ratio(total, divisor):
    """`total / divisor` (a Decimal and a positive whole number) rounded half up to two decimals, printed with two."""
    with localcontext() as ctx:
        ctx.prec, ctx.Emax, ctx.Emin = MAX_PREC, MAX_EMAX, MIN_EMIN
        scaled, divisor = abs(total) * 100, Decimal(divisor)
        cents = (2 * scaled + divisor) // (2 * divisor)  # floor(scaled / divisor + 1/2): half up, exact
        text = fmt_decimal(cents.scaleb(-2))
    return "-" + text if total < 0 and cents else text


def _need_number(value):
    number = to_decimal(value)
    if number is None:
        raise TabulaError("%r is not a number" % value)
    return number


def _need_cell_number(table, row_number, column, value):
    """The Decimal in one cell; the mistake names the file, the row (1-based, file order) and the column."""
    try:
        return _need_number(value)
    except TabulaError as exc:
        raise TabulaError("%s: row %d: column %r: %s" % (table.source, row_number, column, exc))


def _need_count(arg, name):
    if arg is None or not arg.isdigit():
        raise TabulaError("%s needs a whole number argument, got %r" % (name, arg))
    return int(arg)


def _need_decimal_arg(arg, name):
    number = None if arg is None else to_decimal(arg)
    if number is None:
        raise TabulaError("%s needs a number argument, got %r" % (name, arg))
    return number


def _no_arg(name, arg):
    if arg is not None:
        raise TabulaError("%s takes no argument, got %r" % (name, arg))


def _need_text(arg, name):
    if arg is None:
        raise TabulaError("%s needs an argument" % name)
    return arg


# --- the table -----------------------------------------------------------------------------------------------

class Table:
    """Column names and rows of strings. `source` names where it came from, for messages."""

    def __init__(self, columns, rows, source="<table>"):
        self.columns = list(columns)
        self.rows = [list(r) for r in rows]
        self.source = source

    def __len__(self):
        return len(self.rows)

    def index(self, name):
        """Position of a column; TabulaError when there is none."""
        try:
            return self.columns.index(name)
        except ValueError:
            raise TabulaError("%s: no column %r (columns: %s)" % (self.source, name, ", ".join(self.columns)))

    def column(self, name):
        at = self.index(name)
        return [row[at] for row in self.rows]

    def dicts(self):
        return [dict(zip(self.columns, row)) for row in self.rows]

    def with_rows(self, rows, columns=None):
        return Table(self.columns if columns is None else columns, rows, self.source)


def parse_text(text, source):
    """CSV text into a Table. Blank lines are ignored; every row must have as many fields as the header."""
    if text.startswith("﻿"):
        text = text[1:]
    reader = csv.reader(io.StringIO(text, newline=""))
    columns, rows = None, []
    try:
        for fields in reader:
            if not fields:
                continue
            if columns is None:
                for name in fields:
                    if not name.strip():
                        raise TabulaError("%s: line %d: empty column name" % (source, reader.line_num))
                if len(set(fields)) != len(fields):
                    raise TabulaError("%s: line %d: duplicate column name" % (source, reader.line_num))
                columns = fields
                continue
            if len(fields) != len(columns):
                raise TabulaError("%s: line %d: expected %d fields, found %d"
                                  % (source, reader.line_num, len(columns), len(fields)))
            rows.append(fields)
    except csv.Error as exc:
        raise TabulaError("%s: line %d: %s" % (source, reader.line_num, exc))
    if columns is None:
        raise TabulaError("%s: no header line" % source)
    return Table(columns, rows, source)


def load(path):
    """Read a CSV file (UTF-8, optional byte order mark, LF or CRLF) into a Table."""
    try:
        with open(path, "rb") as fh:
            raw = fh.read()
    except OSError as exc:
        raise TabulaError("%s: cannot read: %s" % (path, exc.strerror or exc))
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        raise TabulaError("%s: not valid UTF-8" % path)
    return parse_text(text, path)


# --- output --------------------------------------------------------------------------------------------------

def render_text(table):
    cells = [table.columns] + table.rows
    widths = [max(len(row[i]) for row in cells) for i in range(len(table.columns))]
    lines = ["  ".join(cell.ljust(width) for cell, width in zip(row, widths)).rstrip() for row in cells]
    return "\n".join(lines) + "\n"


def render_csv(table):
    out = io.StringIO()
    writer = csv.writer(out, lineterminator="\n")
    writer.writerow(table.columns)
    writer.writerows(table.rows)
    return out.getvalue()


def render_json(table):
    return json.dumps(table.dicts(), ensure_ascii=False) + "\n"


RENDERERS = {"text": render_text, "csv": render_csv, "json": render_json}


def render(table, fmt="text"):
    return RENDERERS[fmt](table)


# --- transforms: one small function each, `name` or `name:ARG` in `apply` ----------------------------------------


def parse_spec(spec):
    """`name` or `name:arg` into (function, arg); the argument is everything after the first colon."""
    name, _, arg = spec.partition(":")
    if name not in TRANSFORMS:
        raise TabulaError("unknown transform %r" % name)
    return TRANSFORMS[name], (arg if ":" in spec else None)


def apply_transforms(value, specs):
    for fn, arg in specs:
        value = fn(value, arg)
    return value


# --- commands ------------------------------------------------------------------------------------------------

def _need_args(args, count, usage):
    if len(args) != count:
        raise UsageError("usage: %s %s" % (PROG, usage))


def _need_min_args(args, count, usage):
    if len(args) < count:
        raise UsageError("usage: %s %s" % (PROG, usage))


def cmd_show(args, opts):
    _need_args(args, 1, "show FILE")
    return load(args[0])


def cmd_head(args, opts):
    _need_args(args, 2, "head FILE N")
    if not args[1].isdigit():
        raise UsageError("head: N must be a whole number, got %r" % args[1])
    table = load(args[0])
    return table.with_rows(table.rows[:int(args[1])])


def cmd_cols(args, opts):
    _need_args(args, 1, "cols FILE")
    table = load(args[0])
    return Table(["position", "column"], [[str(i + 1), name] for i, name in enumerate(table.columns)], table.source)


def cmd_apply(args, opts):
    _need_min_args(args, 3, "apply FILE COLUMN TRANSFORM...")
    table = load(args[0])
    at = table.index(args[1])
    specs = [parse_spec(s) for s in args[2:]]
    rows = []
    for number, row in enumerate(table.rows, 1):
        row = list(row)
        try:
            row[at] = apply_transforms(row[at], specs)
        except TabulaError as exc:
            raise TabulaError("%s: row %d: %s" % (table.source, number, exc))
        rows.append(row)
    return table.with_rows(rows)


SORT_MODIFIERS = ("num", "desc")


def parse_sort_key(key):
    """(column, numeric, descending) from `COLUMN[:num][:desc]` in either order."""
    column, *mods = key.split(":")
    if not column:
        raise UsageError("sort: empty column name in key %r" % key)
    for mod in mods:
        if mod not in SORT_MODIFIERS:
            raise UsageError("sort: unknown modifier %r in key %r (use num or desc)" % (mod, key))
    if len(set(mods)) != len(mods):
        raise UsageError("sort: modifier given twice in key %r" % key)
    return column, "num" in mods, "desc" in mods


def cmd_sort(args, opts):
    _need_min_args(args, 2, "sort FILE KEY...")
    keys = [parse_sort_key(k) for k in args[1:]]
    table = load(args[0])
    positions = [table.index(column) for column, _, _ in keys]
    numbers = {}
    for number, row in enumerate(table.rows, 1):
        for (column, numeric, _), at in zip(keys, positions):
            if numeric:
                numbers[number, at] = _need_cell_number(table, number, column, row[at])
    order = list(range(len(table.rows)))
    for (column, numeric, desc), at in reversed(list(zip(keys, positions))):
        if numeric:
            order.sort(key=lambda i: numbers[i + 1, at], reverse=desc)
        else:
            order.sort(key=lambda i: table.rows[i][at], reverse=desc)
    return table.with_rows([table.rows[i] for i in order])


FILTER_OPERATORS = ("==", "!=", ">=", "<=", ">", "<", "~")


def parse_condition(arg):
    """(column, operator, value) from `COLUMN OP VALUE`: the first operator in the argument, the longer one on a tie."""
    for at in range(len(arg)):
        for op in FILTER_OPERATORS:
            if arg.startswith(op, at):
                if at == 0:
                    raise UsageError("filter: no column name before the operator in %r" % arg)
                return arg[:at], op, arg[at + len(op):]
    raise UsageError("filter: no operator in condition %r (use ==, !=, >=, <=, >, < or ~)" % arg)


def _condition_holds(cell, op, value, number):
    if op == "~":
        return value.lower() in cell.lower()
    left = to_decimal(cell) if number is not None else None
    a, b = (left, number) if left is not None else (cell, value)
    return {"==": a == b, "!=": a != b, ">=": a >= b, "<=": a <= b, ">": a > b, "<": a < b}[op]


def cmd_filter(args, opts):
    _need_min_args(args, 2, "filter FILE CONDITION...")
    conditions = [parse_condition(c) for c in args[1:]]
    table = load(args[0])
    tests = [(table.index(column), op, value, to_decimal(value)) for column, op, value in conditions]
    return table.with_rows([row for row in table.rows
                            if all(_condition_holds(row[at], op, value, number) for at, op, value, number in tests)])


AGGREGATE_FUNCTIONS = ("sum", "min", "max", "mean")


def parse_aggregate(arg):
    """(function, column) from `count` or `sum|min|max|mean:COLUMN`; the column of `count` is None."""
    function, colon, column = arg.partition(":")
    if arg == "count":
        return "count", None
    if function not in AGGREGATE_FUNCTIONS or not colon or not column:
        raise UsageError("group: unknown aggregate %r (use count, sum:COLUMN, min:COLUMN, max:COLUMN or mean:COLUMN)"
                         % arg)
    return function, column


def _aggregate(function, numbers):
    if function == "sum":
        return fmt_decimal(exact_sum(numbers))
    if function == "min":
        return fmt_decimal(min(numbers))
    if function == "max":
        return fmt_decimal(max(numbers))
    return fmt_ratio(exact_sum(numbers), len(numbers))


def cmd_group(args, opts):
    _need_min_args(args, 3, "group FILE BY AGGREGATE...")
    if len(set(args[2:])) != len(args[2:]):
        raise UsageError("group: aggregate %r given twice" % next(a for a in args[2:] if args[2:].count(a) > 1))
    aggregates = [parse_aggregate(a) for a in args[2:]]
    table = load(args[0])
    by = table.index(args[1])
    names = [args[1]] + [a.replace(":", "_") for a in args[2:]]
    if args[1] in names[1:]:
        raise TabulaError("%s: column %r would appear twice in the result" % (table.source, args[1]))
    positions = {column: table.index(column) for _, column in aggregates if column is not None}
    cells = {column: [] for column in positions}  # the numbers of each aggregated column, row by row
    for number, row in enumerate(table.rows, 1):
        for column, at in positions.items():
            cells[column].append(_need_cell_number(table, number, column, row[at]))
    groups = {}
    for i, row in enumerate(table.rows):
        groups.setdefault(row[by], []).append(i)
    rows = []
    for key, members in groups.items():
        out = [key]
        for function, column in aggregates:
            out.append(str(len(members)) if function == "count"
                       else _aggregate(function, [cells[column][i] for i in members]))
        rows.append(out)
    return Table(names, rows, table.source)


def cmd_join(args, opts):
    _need_args(args, 3, "join LEFT RIGHT KEY")
    left, right = load(args[0]), load(args[1])
    at_left, at_right = left.index(args[2]), right.index(args[2])
    kept = [i for i in range(len(right.columns)) if i != at_right]
    names = left.columns + [right.columns[i] + "_right" if right.columns[i] in left.columns else right.columns[i]
                            for i in kept]
    for name in names:
        if names.count(name) > 1:
            raise TabulaError("%s: column %r would appear twice in the result" % (left.source, name))
    matches = {}
    for row in right.rows:
        matches.setdefault(row[at_right], []).append([row[i] for i in kept])
    empty = [""] * len(kept)
    rows = []
    for row in left.rows:
        found = matches.get(row[at_left]) or ([empty] if opts["kind"] == "left" else [])
        rows.extend(row + extra for extra in found)
    return Table(names, rows, left.source)


def cmd_pivot(args, opts):
    _need_args(args, 4, "pivot FILE ROW COLUMN VALUE")
    if args[1] == args[2]:
        raise UsageError("pivot: ROW and COLUMN must be different columns, got %r twice" % args[1])
    table = load(args[0])
    at_row, at_column, at_value = table.index(args[1]), table.index(args[2]), table.index(args[3])
    sums, columns = {}, {}  # the numbers per ROW value and COLUMN value; the COLUMN values in order of appearance
    for number, row in enumerate(table.rows, 1):
        label = row[at_column]
        if not label.strip():
            raise TabulaError("%s: row %d: column %r: empty value" % (table.source, number, args[2]))
        if label == args[1]:
            raise TabulaError("%s: column %r would appear twice in the result" % (table.source, label))
        cell = _need_cell_number(table, number, args[3], row[at_value])
        columns.setdefault(label, None)
        sums.setdefault(row[at_row], {}).setdefault(label, []).append(cell)
    rows = [[key] + [fmt_decimal(exact_sum(found[label])) if label in found else "0" for label in columns]
            for key, found in sums.items()]
    return Table([args[1]] + list(columns), rows, table.source)


def cmd_dedupe(args, opts):
    _need_min_args(args, 2, "dedupe FILE KEY...")
    table = load(args[0])
    positions = [table.index(name) for name in args[1:]]
    chosen = {}  # the key values -> the position of the row that stays
    for at, row in enumerate(table.rows):
        key = tuple(row[p] for p in positions)
        if opts["keep"] == "last" or key not in chosen:
            chosen[key] = at
    return table.with_rows([table.rows[at] for at in sorted(chosen.values())])


STATS_COLUMNS = ["column", "count", "min", "max", "mean", "median"]


def cmd_stats(args, opts):
    _need_min_args(args, 2, "stats FILE COLUMN...")
    table = load(args[0])
    positions = [table.index(name) for name in args[1:]]
    found = [[] for _ in positions]  # the numbers of each asked column (not the empty cells), row by row
    for number, row in enumerate(table.rows, 1):
        for numbers, name, at in zip(found, args[1:], positions):
            if row[at].strip():
                numbers.append(_need_cell_number(table, number, name, row[at]))
    rows = []
    for name, numbers in zip(args[1:], found):
        if not numbers:
            rows.append([name, "0", "", "", "", ""])
            continue
        numbers.sort()
        middle = len(numbers) // 2
        halves = numbers[middle - 1:middle + 1] if len(numbers) % 2 == 0 else [numbers[middle]]
        rows.append([name, str(len(numbers)), _aggregate("min", numbers), _aggregate("max", numbers),
                     _aggregate("mean", numbers), fmt_ratio(exact_sum(halves), len(halves))])
    return Table(STATS_COLUMNS, rows, table.source)


COMMANDS = {
    "show": (cmd_show, "show FILE", "print a table"),
    "head": (cmd_head, "head FILE N", "the first N rows"),
    "cols": (cmd_cols, "cols FILE", "the column names, numbered"),
    "apply": (cmd_apply, "apply FILE COLUMN TRANSFORM...", "run transforms over one column"),
    "sort": (cmd_sort, "sort FILE KEY...", "rows sorted by KEY (COLUMN[:num][:desc])"),
    "filter": (cmd_filter, "filter FILE CONDITION...", "rows where every CONDITION (COLUMN OP VALUE) holds"),
    "group": (cmd_group, "group FILE BY AGGREGATE...", "one row per BY value: count, sum:/min:/max:/mean:COLUMN"),
    "join": (cmd_join, "join LEFT RIGHT KEY", "join two files on KEY (--kind inner|left)"),
    "pivot": (cmd_pivot, "pivot FILE ROW COLUMN VALUE", "COLUMN values as columns, summing VALUE per ROW"),
    "dedupe": (cmd_dedupe, "dedupe FILE KEY...", "drop rows repeating the KEY columns (--keep first|last)"),
    "stats": (cmd_stats, "stats FILE COLUMN...", "count, min, max, mean and median of each COLUMN"),
}


# --- the command line ----------------------------------------------------------------------------------------

def usage_text():
    options = " ".join("[--%s %s]" % (name, "|".join(allowed)) for name, (allowed, _) in VALUE_OPTIONS.items())
    lines = ["usage: %s %s COMMAND ARGS..." % (PROG, options), "", "commands:"]
    width = max(len(u) for _, u, _ in COMMANDS.values())
    for _, use, what in COMMANDS.values():
        lines.append("  %s  %s" % (use.ljust(width), what))
    return "\n".join(lines) + "\n"


def parse_args(argv):
    """(command, positional arguments, options) from the command line."""
    opts = {name: default for name, (_, default) in VALUE_OPTIONS.items()}
    rest, i = [], 0
    while i < len(argv):
        arg = argv[i]
        name = arg[2:].split("=", 1)[0] if arg.startswith("--") else None
        if arg in ("-h", "--help"):
            opts["help"] = True
        elif name in VALUE_OPTIONS:
            if "=" in arg:
                value = arg.split("=", 1)[1]
            else:
                i += 1
                if i >= len(argv):
                    raise UsageError("--%s needs a value" % name)
                value = argv[i]
            allowed = VALUE_OPTIONS[name][0]
            if value not in allowed:
                raise UsageError("--%s must be one of %s, got %r" % (name, ", ".join(allowed), value))
            opts[name] = value
        elif arg.startswith("-") and len(arg) > 1:
            raise UsageError("unknown option %s" % arg)
        else:
            rest.append(arg)
        i += 1
    if opts.get("help"):
        return None, rest, opts
    if not rest:
        raise UsageError("no command given")
    if rest[0] not in COMMANDS:
        raise UsageError("unknown command %r" % rest[0])
    return rest[0], rest[1:], opts


def main(argv=None):
    argv = sys.argv[1:] if argv is None else list(argv)
    try:
        name, args, opts = parse_args(argv)
        if name is None:
            sys.stdout.write(usage_text())
            return 0
        table = COMMANDS[name][0](args, opts)
        sys.stdout.write(render(table, opts["format"]))
        sys.stdout.flush()
        return 0
    except UsageError as exc:
        print("%s: %s" % (PROG, exc), file=sys.stderr)
        return 2
    except TabulaError as exc:
        print("%s: %s" % (PROG, exc), file=sys.stderr)
        return 1
    except BrokenPipeError:
        return 0
    except OSError as exc:
        # stdout cannot be written (a full disk, say): say so, and keep the exit-time flush from failing again.
        try:
            os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
        except (OSError, ValueError, AttributeError):
            pass
        print("%s: cannot write output: %s" % (PROG, exc.strerror or exc), file=sys.stderr)
        return 1
import sys

from .engine import main

sys.exit(main())
"""The two kinds of failure a command can end in."""


class TabulaError(Exception):
    """A mistake in a file or in what was asked for; the command line ends with exit status 1."""


class UsageError(Exception):
    """A command line that is not shaped right; the command line ends with exit status 2."""
"""tabula: small tools for CSV tables."""
from .engine import Table, load, main, render
from .errors import TabulaError, UsageError

__all__ = ["Table", "TabulaError", "UsageError", "load", "main", "render"]
__version__ = "0.3.0"

